using System.Runtime.InteropServices.WindowsRuntime;
using System.Security.Cryptography;
using Windows.Graphics.Imaging;
using Windows.Storage.Streams;
using Xunit;

namespace Deckle.Folders.Tests;

// The picture a model is handed is a reduced JPEG, made with what Windows
// ships, upright, and the original file is only read. Every image here is
// generated by the test.
[Collection(FoldersProviderCollection.Name)]
[Trait("Category", "integration")]
public sealed class PhotoPictureReducerTests
{
    [Fact]
    public async Task ALargePhotoComesOutAsAJpegOfAThousandPixelsOnItsLongSide()
    {
        using var scratch = new ScratchFolder();
        string photo = await WriteJpegAsync(scratch, "big.JPG", 3000, 2000);

        byte[]? jpeg = await PhotoPictureReducer.ReduceAsync(photo, shell: null, CancellationToken.None);

        Assert.NotNull(jpeg);
        (uint width, uint height, Guid codec) = await ReadAsync(jpeg);
        Assert.Equal(BitmapDecoder.JpegDecoderId, codec);
        Assert.Equal(1024u, width);
        Assert.Equal(683u, height);
    }

    [Fact]
    public async Task APortraitPhotoComesOutUpright()
    {
        using var scratch = new ScratchFolder();
        // Stored landscape, shown portrait: Exif orientation 6 turns it a
        // quarter clockwise.
        string photo = await WriteJpegAsync(scratch, "portrait.JPG", 300, 200, orientation: 6);

        byte[]? jpeg = await PhotoPictureReducer.ReduceAsync(photo, shell: null, CancellationToken.None, longSide: 150);

        (uint width, uint height, _) = await ReadAsync(jpeg!);
        Assert.Equal(100u, width);
        Assert.Equal(150u, height);
    }

    [Fact]
    public async Task ASmallPhotoIsNotEnlarged()
    {
        using var scratch = new ScratchFolder();
        string photo = await WriteJpegAsync(scratch, "small.JPG", 640, 480);

        (uint width, uint height, _) = await ReadAsync((await PhotoPictureReducer.ReduceAsync(photo, null, CancellationToken.None))!);

        Assert.Equal((640u, 480u), (width, height));
    }

    [Fact]
    public async Task TheOriginalIsOnlyRead()
    {
        using var scratch = new ScratchFolder();
        string photo = await WriteJpegAsync(scratch, "big.JPG", 2000, 1500);
        byte[] before = SHA256.HashData(File.ReadAllBytes(photo));
        DateTime written = File.GetLastWriteTimeUtc(photo);

        await PhotoPictureReducer.ReduceAsync(photo, null, CancellationToken.None);

        Assert.Equal(before, SHA256.HashData(File.ReadAllBytes(photo)));
        Assert.Equal(written, File.GetLastWriteTimeUtc(photo));
        Assert.Equal([photo], Directory.GetFiles(Path.GetDirectoryName(photo)!));
    }

    [Fact]
    public async Task AFileNoCodecReadsIsUnreadable()
    {
        using var scratch = new ScratchFolder();
        string photo = scratch.File("not a picture", "broken.JPG");

        Assert.Null(await PhotoPictureReducer.ReduceAsync(photo, null, CancellationToken.None));
    }

    [Fact]
    public async Task AMissingFileIsUnreadable()
    {
        using var scratch = new ScratchFolder();
        Assert.Null(await PhotoPictureReducer.ReduceAsync(Path.Combine(scratch.Path, "gone.JPG"), null, CancellationToken.None));
    }

    [Theory]
    [InlineData(4000u, 3000u, 1024, 1024u, 768u)]
    [InlineData(3000u, 4000u, 1024, 768u, 1024u)]
    [InlineData(800u, 600u, 1024, 800u, 600u)]
    [InlineData(10000u, 10u, 1024, 1024u, 1u)]
    public void FitKeepsTheProportions(uint width, uint height, int longSide, uint expectedWidth, uint expectedHeight) =>
        Assert.Equal((expectedWidth, expectedHeight), PhotoPictureReducer.Fit(width, height, longSide));

    internal static async Task<string> WriteJpegAsync(ScratchFolder scratch, string name, int width, int height, ushort? orientation = null)
    {
        byte[] pixels = new byte[width * height * 4];
        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                int i = (y * width + x) * 4;
                pixels[i] = (byte)(x * 255 / width);
                pixels[i + 1] = (byte)(y * 255 / height);
                pixels[i + 2] = 128;
                pixels[i + 3] = 255;
            }
        }

        using var output = new InMemoryRandomAccessStream();
        BitmapEncoder encoder = await BitmapEncoder.CreateAsync(BitmapEncoder.JpegEncoderId, output);
        encoder.SetPixelData(BitmapPixelFormat.Bgra8, BitmapAlphaMode.Ignore, (uint)width, (uint)height, 96, 96, pixels);
        if (orientation is { } o)
        {
            await encoder.BitmapProperties.SetPropertiesAsync(new BitmapPropertySet
            {
                ["System.Photo.Orientation"] = new BitmapTypedValue(o, Windows.Foundation.PropertyType.UInt16),
            });
        }
        await encoder.FlushAsync();

        string path = Path.Combine(scratch.Folder("Shoot"), name);
        using var copy = new MemoryStream();
        output.Seek(0);
        await output.AsStreamForRead().CopyToAsync(copy);
        await File.WriteAllBytesAsync(path, copy.ToArray());
        return path;
    }

    static async Task<(uint Width, uint Height, Guid Codec)> ReadAsync(byte[] jpeg)
    {
        using var stream = new InMemoryRandomAccessStream();
        await stream.WriteAsync(jpeg.AsBuffer());
        stream.Seek(0);
        BitmapDecoder decoder = await BitmapDecoder.CreateAsync(stream);
        return (decoder.PixelWidth, decoder.PixelHeight, decoder.DecoderInformation.CodecId);
    }
}
